/**
 * Background jobs. A job records the request id of the request that enqueued
 * it, and a job that fails while running is logged under that same id -- so a
 * failure in the background is traceable back to the request that caused it.
 */
import { AppLogger, type Sink } from "../platform/logging/AppLogger.ts";

export interface Job {
  readonly kind: string;
  readonly payload: unknown;
}

export interface QueuedJob extends Job {
  readonly id: string;
  readonly requestId: string;
  readonly enqueuedAt: number;
}

export type JobRunner = (job: QueuedJob) => Promise<void> | void;

export class JobQueue {
  readonly #jobs: QueuedJob[] = [];
  readonly #sink: Sink | undefined;
  #next = 1;

  /** A sink can be supplied so a test can observe what a failing job logs; production uses AppLogger's default. */
  constructor(sink?: Sink) {
    this.#sink = sink;
  }

  enqueue(job: Job, opts: { requestId: string }): string {
    const id = `job-${this.#next++}`;
    this.#jobs.push({ ...job, id, requestId: opts.requestId, enqueuedAt: Date.now() });
    return id;
  }

  get size(): number {
    return this.#jobs.length;
  }

  /**
   * Runs every queued job in order. A failing job is dropped and the rest still run, and the
   * failure is logged under the request id of the request that enqueued that job.
   */
  async run(runner: JobRunner): Promise<{ ran: number; failed: number }> {
    let ran = 0;
    let failed = 0;
    while (this.#jobs.length > 0) {
      const job = this.#jobs.shift()!;
      try {
        await runner(job);
        ran++;
      } catch (err) {
        this.#logFailure(job, err);
        failed++;
      }
    }
    return { ran, failed };
  }

  /**
   * One error line per failed job, under that job's own request id (never a fresh one). The
   * payload is deliberately left out: it is arbitrary request body, and what makes the failure
   * traceable is the request id plus the job id.
   *
   * Logging must not change what run() reports, so a sink that throws is swallowed here rather
   * than rejecting run() and dropping the jobs still queued behind this one.
   */
  #logFailure(job: QueuedJob, err: unknown): void {
    try {
      const log = AppLogger.withRequestId(job.requestId, this.#sink);
      log.error("background job failed", {
        jobId: job.id,
        kind: job.kind,
        error: err instanceof Error ? err.message : String(err),
      });
    } catch {
      // A broken logger must not take the queue down with it.
    }
  }
}

